def load(name):
    return json.loads((EVIDENCE / name).read_text(encoding="utf-8-sig"))


def link(src, target, label=None):
    relative = os.path.relpath(target, Path(src).parent).replace("\\", "/")
    return f"[{label or Path(target).stem}]({quote(relative, safe='/.-_')})"


def table(headers, rows):
    def cell(value):
        return str(value).replace("|", "\\|").replace("\n", "<br>")
    return "\n".join(["| " + " | ".join(map(cell, headers)) + " |", "| " + " | ".join("---" for _ in headers) + " |"] + ["| " + " | ".join(map(cell, row)) + " |" for row in rows]) + "\n"


def fmt(x):
    if x is None or isinstance(x, float) and not math.isfinite(x):
        return "нет значения"
    if isinstance(x, float):
        return f"{x:.7g}"
    return str(x)


def add(path, title, body, kind="guide", parent=HOME, **properties):
    assert path not in NOTES, path
    metadata = {"title": title, "type": kind, "reviewed": "2026-09-10", **properties}
    yaml = "\n".join(f"{key}: {json.dumps(value, ensure_ascii=False)}" for key, value in metadata.items())
    nav = "" if path == HOME else link(path, HOME, "Карта данных") + (" · " + link(path, parent) if parent != HOME else "") + "\n\n"
    NOTES[path] = f"---\n{yaml}\n---\n\n{nav}# {title}\n\n{body.strip()}\n"


def issue_path(code):
    return f"Неопределённости/{code}.md"


def concept_path(name):
    return f"Понятия/{name}.md"


def signal_path(stage, tag):
    return str(Path(AVT if stage == "avt" else HT).parent / f"{'AVT' if stage == 'avt' else 'HT'}-{tag}.md").replace("\\", "/")


def point_id(name):
    number = re.search(r"Точка отбора '([^']+)'", name).group(1)
    return ("AVT" if "'АВТ'" in name else "HT") + number


def point_path(pid):
    return f"Источники/ЛИМС/{POINT_NAMES[pid]}/{POINT_NAMES[pid]}.md"


def lab_path(record):
    pid = point_id(record["point"])
    # Column-pair suffix preserves identity even when names are duplicated.
    return str(Path(point_path(pid)).parent / f"LIMS-{pid}-{record['parameter']}-{record['excel_columns'].replace(':', '-')}.md").replace("\\", "/")


def pak_path(key):
    return f"Источники/ПАК/PAK-{'Sulfur' if key == 'sulfur' else 'D15'}.md"


def stats(p):
    labels = [("Числовых значений", "count"), ("Пропусков после числового разбора", "missing"), ("Уникальных чисел", "nunique"), ("Минимум", "min"), ("1-й процентиль", "p01"), ("5-й процентиль", "p05"), ("Медиана", "median"), ("95-й процентиль", "p95"), ("99-й процентиль", "p99"), ("Максимум", "max"), ("Среднее", "mean"), ("Стандартное отклонение", "std"), ("Нулей", "zero_count"), ("Отрицательных", "negative_count"), ("Максимум одинаковых строк подряд", "longest_constant_rows")]
    return table(["Характеристика", "Значение"], [(label, fmt(p.get(key))) for label, key in labels])


def coverage(p):
    return table(["Время", "Значение"], [("Начало", p["start"]), ("Конец", p["end"]), ("Медианный шаг, часов", fmt(p["median_step_seconds"] / 3600)), ("Максимальный разрыв, часов", fmt(p["max_gap_hours"])), ("Нераспознанных дат", p["invalid_dates"]), ("Повторных временных меток", p["duplicate_timestamps"])])


