def prop(parameter):
    if "Sulfur" in parameter:
        return "Сера"
    if parameter == "D15":
        return "Плотность D15"
    if parameter in ("CFPP", "CloudPoint", "CloudPoint_1", "PourPoint", "FilterabilityLimit.T"):
        return "Холодные свойства"
    if parameter == "FlashPoint":
        return "Температура вспышки"
    if parameter == "CetaneNumber":
        return "Цетановое число"
    if parameter == "ViscosityK":
        return "Кинематическая вязкость"
    return "Фракционный состав"


def main(output):
    summary = load("profile_summary.json")
    dictionary = load("tag_dictionary.json")
    telemetry = load("telemetry_profile.json")
    inventories = load("source_inventory.json")
    workbooks = load("workbooks_structure.json")
    csvs = load("csv_structure.json")
    findings = load("findings_checks.json")
    labs = summary["lims"]
    wb = {x["file"]: x for x in workbooks}
    labbook = next(x for x in workbooks if x["file"].startswith("ЛИМС"))
    pakbook = next(x for x in workbooks if x["file"].startswith("Выгрузка"))
    tagsbook = wb["Теги_хакатон.xlsx"]
    refs = {x["sheet"]: x for x in tagsbook["sheets"]}
    profiles = {(p["stage"], p["tag"]): p for p in telemetry}
    mappings = {(p["stage"], p["tag"]): p for p in dictionary}
    groups = defaultdict(list)
    for p in labs:
        groups[point_id(p["point"])].append(p)
    formulas = []
    for rownum, row in enumerate(load("vak_source.json")[1:], 2):
        for column in (0, 2, 4):
            if row[column]:
                name, expression = row[column:column + 2]
                stage = "avt" if column < 4 else "242000"
                local_expression = re.sub(r"LIMS:[A-Za-z0-9_.:%-]+", "", expression).replace("x", "*")
                dependencies = sorted(set(re.findall(r"(?<![A-Za-z0-9])([A-Z]\d+)\b", local_expression)), key=lambda t: int(re.search(r"\d+", t).group()))
                assert all((stage, tag) in mappings for tag in dependencies), (name, dependencies, [tag for tag in dependencies if (stage, tag) not in mappings])
                formulas.append({"name": name, "expression": expression, "cell": f"ВАК!{chr(66 + column)}{rownum}", "stage": stage, "inputs": dependencies, "path": f"Источники/Справочник/ВАК/VAK-{name.replace(':', '-')}.md"})

    # Each issue includes evidence, consequence, interim rule and resolution criterion.
    issues = {
        "Q01-Смысл-тегов": ("Соответствия тегов и единицы КИП", "Все 97 тегов имеют описания, но подтверждённые единицы и признаки управляемости отсутствуют. ГО T6 описан как анализатор серы, медиана 362.6615; W7 тоже описан как сера, медиана 0.17275. P8 описан как температура, медиана 0.174; T11 как массовый расход, медиана 363.6128; F25 как виртуальная температура вспышки, медиана 13091.37. Корреляция T6 с T5 = 0.997823 не доказывает ошибку, но усиливает вопрос к соответствию.", "Сохранить исходные имена и описания; единицы оставить неизвестными. Анализировать статистически, не переводить в физические уставки и не переназывать по букве.", "Получить соответствие экспортного тега промышленному тегу, единицы, масштаб, способ измерения, признак уставки и допустимые воздействия.", [HT, signal_path("242000", "T6"), signal_path("242000", "W7"), signal_path("242000", "P8"), signal_path("242000", "T11"), signal_path("242000", "F25")]),
        "Q02-Единицы-ЛИМС": ("Единицы ЛИМС и расхождения справочника", "У АВТ-1 в E2 указан 50%.T, но E3 = кг/м3; G2 = EBP.T, G3 = % об.; K2 = D15, K3 = °C. M2 = I350, M3 = °C, хотя по обычному смыслу I350 ожидается доля отгона. В ЛА!A1 продукт ФРАКЦ_ДИЗ, в выгрузке для АВТ-1 Дизельное топливо. ЛА!F7 содержит Т98%, в выгрузке CO:CP записан 95%.T.", "Хранить unit_source отдельно от ожидаемой единицы. Не сдвигать автоматически строку единиц или список показателей и не переименовывать T95 в T98.", "Подтвердить единицу и метод для каждой спорной пары, происхождение CloudPoint_1, названия продукта и соответствие ЛА фактической выгрузке.", [point_path("AVT1"), "Источники/Справочник/ЛА.md"]),
        "Q03-Время-и-доступность": ("Время пробы, публикации и транспортный лаг", "Выгрузки содержат даты, но не дают отдельного available_at, часового пояса, продолжительности анализа и трассировки одной порции продукта между установками. Разная пара Excel может иметь другую дату в той же строке.", "Для ретроспективной диагностики использовать время источника. Онлайн-эксперимент строить с явно заданными задержками и анализом чувствительности; неизвестный лаг не объявлять нулевым фактом. Backward join ограничить допустимым возрастом.", "Уточнить смысл даты, момент публикации, задержки ПАК и ЛИМС, транспортные времена и смену режима пробоотбора.", [LIMS, PAK, "Связи и синхронизация.md"]),
        "Q04-Плато-ПАК": ("ПАК может сохранять старое значение", "Сера неизменна 6732 строки с 2024-03-16 18:20 до 2024-05-02 12:10, значение 7.7051606. Следующие длинные плато: 18.2222 суток в июне-июле 2026 и 12.0556 суток в апреле 2026. Регулярные метки времени не подтверждают обновление измерения.", "Хранить продолжительность неизменности и флаг качества; не обучаться на плато как на независимых подтверждениях нормы. Само постоянство не доказывает неисправность.", "Получить коды качества, причины остановок/замещения и правила удержания последнего значения в архиве.", [pak_path("sulfur")]),
        "Q05-Аномалии-телеметрии": ("Почти постоянные и отрицательные сигналы", "AVT-D10 содержит только 307 (189207 строк) и 240 (10 строк), хотя описан как плотность. AVT-F26, расход пара в К6, отрицателен в 117719 строках. У нескольких тегов встречается 307; универсальный код отсутствия данных не подтверждён.", "Пометить D10 как непригодный для физической интерпретации до проверки. Для остальных завести отдельные флаги и сравнение периодов, не заменять все отрицательные и все 307 на пропуски.", "Уточнить коды замещения, знак потока, шкалы, остановочные режимы и историю исправности.", [signal_path("avt", "D10"), signal_path("avt", "F26")]),
        "Q06-Экстремальная-сера": ("Лабораторная сера 2120 мг/кг", "ГО-2: 2120 мг/кг 2024-04-23 06:30, затем 34 в 09:24 и 107 в 10:00. ПАК в это время на плато 7.7051606. При сопоставлении всех 1462 анализов с предыдущим ПАК не старше 10 минут MAE = 3.28577, медиана абсолютного расхождения = 1.14624, классификация по 10 расходится 283 раза. Это диагностика согласия источников, не качество прогноза модели.", "Сохранить экстремум и флаг проверки. Делать основной отчёт на полном наборе, отдельно показывать чувствительность к исключению подозрительных точек. Не объявлять аварию по одному анализу.", "Подтвердить анализ, единицу, точку, режим запуска/остановки и лабораторный комментарий.", [lab_path(next(p for p in labs if p["parameter"] == "Mg.Sulfur")), pak_path("sulfur")]),
        "Q07-ВАК": ("Формулы ВАК требуют валидации", "ВАК!B5 имеет лишнюю закрывающую скобку и неоднозначный знаменатель F65/F32+F30. Буквальная ВАК!F2 даёт медиану T90 около 202702.44, ВАК!D2 медиану T50 около 880.82. ВАК!F5 и F7 ссылаются на LIMS:24-2000.Pipeline.*, которых нет как точных имён рядов выгрузки.", "Сохранить формулы дословно. Их зависимости можно использовать как кандидаты для исследования, но формулы не включать в safety gate и не исправлять коэффициенты на глаз.", "Получить корректные скобки, версии, единицы входов/выходов, область применимости, соответствие Pipeline точке и данные валидации.", [VAK]),
        "Q08-Блендинг-и-границы": ("Товарный продукт, рецептура и технологические ограничения", "В пакете нет отдельной схемы блендинга/ГО, истории рецептур, полной сезонной спецификации, подтверждённых диапазонов уставок и связи лабораторных точек с конечным блендом. ТЗ задаёт серу <= 10 мг/кг и сумму долей 100%.", "ГО-2 можно выбрать как прокси конечного продукта только с явной маркировкой сценария. Min/max и квантили истории использовать лишь как модельную область, а не промышленное разрешение. Без состава и единиц не считать экономику смешения.", "Нужны компоненты, тип долей, расходы/ёмкости, присадки, марка топлива, границы и скорости изменений уставок.", [SPEC, SCHEME, "Модели и роль данных.md"]),
        "Q09-ПАК-алиас": ("Суффикс .Q и массовая основа ppm", "Справочник ПАК!B2: 24-2000:Mg.Sulfur.Q; Excel ПАК!A1: 24-2000:Mg.Sulfur. В заголовке единица ppm, но не указано, массовая ли это доля. Названия и назначение близки, полного доказательства тождества нет.", "Считать соответствие кандидатом, хранить оба raw-имени. При сравнении с мг/кг явно принять массовую основу ppm как рабочее допущение и проверить его с технологом.", "Уточнить роль .Q, преобразования экспорта и ppm mass/volume basis.", [pak_path("sulfur"), "Источники/Справочник/ПАК-справочник.md"]),
        "Q10-Служебные-ЛИМС": ("Pt Created, счётчики и повторяющиеся названия", "В AJ5, AL5, AR5, AT5, AV5 и AX5 записано Pt Created: это 6 датированных служебных записей. Числовых результатов 36800, датированных записей 36806, сумма заявленных счётчиков 36808. O:P и Q:R у АВТ-1 имеют соответственно 13 и 112 строк вместо заявленных 14 и 113.", "Оставить raw-значение и флаг nonnumeric; числовое поле сделать null. Не превращать Pt Created в 0. Идентичность ряда задавать точкой, названием и исходной парой колонок; CloudPoint и CloudPoint_1 не сливать.", "Уточнить, что считали счётчики, являются ли повторы разными методами/фракциями и где отсутствующие записи.", [LIMS, point_path("AVT1"), point_path("AVT2.1")]),
        "Q11-Надёжность-и-экономика": ("Нет меток отказов и реальной стоимости", "В данных не найдены журнал отказов, ресурс катализатора, цены потоков/энергии, тарифы и стоимости действий. Временная корреляция датчиков с качеством не измеряет причинный эффект изменения уставки.", "Индекс тяжести и энергия могут быть прозрачными прокси с перечисленными входами и допущениями. Не называть индекс вероятностью отказа, а корреляционный прогноз доказанным эффектом управления.", "Нужны события оборудования, ремонты/регенерации, ресурс и стоимость, либо согласованный сценарий прокси.", ["Модели и роль данных.md", SPEC]),
    }
    for code, (title, evidence, interim, question, related) in issues.items():
        path = issue_path(code)
        add(path, title, f"## Что установлено\n\n{evidence}\n\n## Рабочее правило до ответа\n\n{interim}\n\n## Что закроет вопрос\n\n{question}\n\n## Где это влияет\n\n" + "\n".join(f"- {link(path, x)}" for x in related) + f"\n\nОснование: {link(path, PROOF)}; profile_summary.json, findings_checks.json и адреса исходных ячеек выше. Статус ответа на 10.09: подтверждения нет.", "issue", ISSUES, status="open")
    add(ISSUES, "Неопределённости и временные допущения", "Это реестр открытых вопросов, а не список уже согласованных командой решений. В каждой карточке есть факт, временное правило и условие пересмотра.\n\n" + table(["Вопрос", "Статус"], [(link(ISSUES, issue_path(code), title), "Открыт") for code, (title, *_) in issues.items()]) + "\nПри появлении ответа сохраняем дату, автора/источник, дословное подтверждение и список затронутых карточек. Исходное описание не стираем.", "index")

    for name, (meaning, unit, limitation) in PROPERTIES.items():
        path = concept_path(name)
        related = [lab_path(p) for p in labs if prop(p["parameter"]) == name] + [f["path"] for f in formulas if prop(f["name"].split(":")[-1]) == name]
        if name in ("Сера", "Плотность D15"):
            related.append(pak_path("sulfur" if name == "Сера" else "density"))
        add(path, name, f"{meaning}\n\n**Ожидаемая размерность по смыслу:** {unit}. Это пояснение термина, не исправление заголовка источника.\n\n{limitation}\n\n## Где встречается\n\n" + "\n".join(f"- {link(path, x)}" for x in related), "concept", CONCEPTS)
    glossary = {
        "КИП": "Контрольно-измерительные приборы и технологические сигналы. Имена коротких тегов уникальны только внутри установки: AVT-T6 и HT-T6 разные ряды. Справочник определяет заявленный смысл, а его достоверность проверяется отдельно. Наличие датчика не означает, что оператор может менять измеряемую величину напрямую.",
        "ЛИМС": "Лабораторная информационная система. Каждый анализ относится к точке отбора и показателю. По ТЗ лабораторный результат является контрольным фактом качества, но для онлайн-решения нужно знать время его доступности. Повторенное последнее значение не создаёт новую лабораторную пробу.",
        "ПАК": "Поточный аналитический контроль. В пакете представлены сера и расчётная D15. Он даёт более частый контекст, но плато, задержки и расчётное происхождение ограничивают достоверность. При расхождении источников ТЗ задаёт приоритет ЛИМС выше ПАК.",
        "ВАК": "Виртуальный анализатор качества: вычисление свойства продукта из других сигналов. 17 выданных формул не равны 17 готовым проверенным моделям. Для применения нужно проверить имена, единицы, знаменатели, область и соответствие лаборатории. Приоритет ниже ЛИМС и ПАК.",
        "АВТ и гидроочистка": "АВТ разделяет нефть на фракции; ЭЛОУ подготавливает нефть удалением солей и воды. Гидроочистка изменяет состав сырья в присутствии водорода и катализатора, в том числе снижает содержание серы. В ТЗ цепочка продолжается блендингом. Порядок стадий не задаёт точное соединение каждого датчика с каждой лабораторной пробой.",
        "Время и свежесть": "event_time обозначает время события/пробы, available_at время, когда результат мог попасть в решение. Возраст анализа считают относительно выбранного момента решения. При отсутствии available_at задержка является допущением. Отдельно нужен возраст изменения значения: ряд ПАК может иметь свежие даты при старом числе.",
        "Единицы и конвертации": "1 массовый процент = 10000 мг/кг. Например, 0.12 % масс. = 1200 мг/кг. 1 ppm = 1 мг/кг только для массовой доли. Объёмный ppm требует дополнительных данных; массовые и объёмные доли бленда нельзя смешивать. Исходную единицу сохраняем рядом с нормализованной и формулой преобразования.",
        "Качество данных": "Отсутствие NaN подтверждает заполненность таблицы, а не качество измерений. Проверяем диапазон, скачки, длительную неизменность, согласие источников, единицы и доступность. Флаги не обязаны удалять строку: модель может отказаться от оценки или снизить доверие. Min/max истории не является промышленным ограничением.",
        "Точка отбора и фракция": "Точка отбора задаёт место лабораторного контроля. Фракция задаёт часть продукта, например диапазон кипения 240-350. В пакете нет однозначной таблицы точка АВТ -> фракция ВАК -> линия на схеме. Общие слова Дизельное топливо недостаточны для объединения проб.",
    }
    for name, text in glossary.items():
        path = concept_path(name)
        add(path, name, text + f"\n\nСвязанные материалы: {link(path, RULES)}, {link(path, SOURCES)}, {link(path, ISSUES)}.", "concept", CONCEPTS)
    add(CONCEPTS, "Понятия", "Общие определения вынесены сюда, чтобы карточки разных точек ссылались на один смысл показателя. Определение термина и подтверждённая единица конкретного столбца имеют разный статус.\n\n" + "\n".join(f"- {link(CONCEPTS, concept_path(x))}" for x in [*glossary, *PROPERTIES]), "index")

    # CSV source notes and all 97 per-signal cards.
    for stage, parent, title, filename in [("avt", AVT, "АВТ: телеметрия", "avt_tags.csv"), ("242000", HT, "Гидроочистка 24-2000: телеметрия", "242000_tags.csv")]:
        src = next(x for x in csvs if x["file"] == filename)
        head = src["head"]
        timing = summary["telemetry"][stage]
        catalog = []
        for d in [x for x in dictionary if x["stage"] == stage]:
            tag = d["tag"]
            p = profiles[(stage, tag)]
            path = signal_path(stage, tag)
            col = head[0].index(tag)
            timecol = head[0].index("date")
            example = table(["Строка CSV (с заголовком)", "date", tag], [(i, row[timecol], row[col]) for i, row in enumerate(head[1:4], 2)])
            formula_links = [f for f in formulas if f["stage"] == stage and tag in f["inputs"]]
            issue_links = ["Q01-Смысл-тегов"]
            if stage == "avt" and tag in ("D10", "F26"):
                issue_links.append("Q05-Аномалии-телеметрии")
            flags = []
            if p["negative_count"]:
                flags.append(f"Отрицательных значений {p['negative_count']} ({100*p['negative_count']/p['count']:.2f}%). Их допустимость зависит от величины и режима, общей очистки по знаку нет.")
            if p["longest_constant_rows"] >= 144:
                flags.append(f"Самая длинная последовательность одинаковых значений: {p['longest_constant_rows']} строк, {(p['longest_constant_rows']-1)/144:.3f} суток между первой и последней меткой. Проверить удержание значения и режим установки.")
            if p["zero_count"]:
                flags.append(f"Нулей: {p['zero_count']}. Ноль не приравнен к пропуску.")
            if stage == "242000" and tag in ("T6", "W7", "P8", "T11", "F25"):
                flags.insert(0, "Есть предметное сомнение в соответствии описания и числового масштаба; см. Q01. Физическое использование до уточнения ограничено.")
            if stage == "avt" and tag == "D10":
                flags.insert(0, "Всего два значения: 307 в 189207 строках и 240 в 10 строках. Для интерпретации как плотности пока не пригоден.")
            if not flags:
                flags.append("Этот профиль не выявил нулей, отрицательных значений или плато >= суток. Это не проверка калибровки, физического смысла и всех возможных аномалий.")
            related = [x for x in findings["telemetry_near_duplicate_pairs"] if x["stage"] == stage and tag in (x["a"], x["b"])]
            near = "\n".join(f"- {link(path, signal_path(stage, x['b'] if x['a'] == tag else x['a']))}: Pearson {x['pearson']:.6f}; общий период, без удаления аномалий. Это не тождество тегов и не причинный эффект." for x in related)
            meaning = d["description_source"]
            # General interpretation is grounded in words in the source, never tag letters.
            lower = meaning.lower()
            if "температур" in lower:
                reading = "По описанию это температурная характеристика указанного потока/аппарата. Можно исследовать динамику и лаги; числовую шкалу и единицу ещё нужно подтвердить."
            elif "давлен" in lower:
                reading = "По описанию это давление или перепад давления в указанном узле. Абсолютное/избыточное давление, единицу и знак перепада источник не уточняет."
            elif "расход" in lower:
                reading = "По описанию это расход указанного потока. Массовую или объёмную основу нельзя додумывать, если она прямо не названа; единица и знак потока требуют проверки."
            elif "уров" in lower:
                reading = "По описанию это уровень в аппарате. Шкала в процентах или физических единицах и рабочие ограничения не подтверждены."
            else:
                reading = "Надёжная интерпретация ограничена дословным описанием выше. Короткий код не добавляет подтверждённых единиц, типа датчика или управляемости."
            body = f"**Описание в КИП:** {meaning}\n\n{reading}\n\n" + table(["Поле", "Содержание"], [("Источник", f"data/{filename}; колонка {tag}, позиция {col+1} (с 1)"), ("Идентификатор", f"{stage}:{tag}"), ("Справочник", f"Теги_хакатон.xlsx, {d['source_cell']} (код), соседняя колонка слева (описание)"), ("Единица", "Не подтверждена"), ("Управляемость", "Не подтверждена; это не объявление тега неуправляемым"), ("Гранулярность", "Одно архивное значение на метку date каждые 10 минут"), ("Период", f"{timing['start']} .. {timing['end']}")])
            body += f"\n## Как выглядит ряд\n\n{example}\n## Статистика исходного ряда\n\n{stats(p)}\nДоля строк, равных предыдущей: {p['unchanged_adjacent_fraction']:.6f}; знаменатель включает первую строку. Никакие значения из этого профиля не удалены. Диапазоны описывают историю, не технологические пределы.\n\n## На что обратить внимание\n\n" + "\n".join(f"- {x}" for x in flags)
            body += "\n\n" + "; ".join(link(path, issue_path(x)) for x in issue_links)
            body += "\n\n## Где используется\n\n" + ("\n".join(f"- {link(path, f['path'], f['name'])} (вход формулы {f['cell']}; формула не валидирована)." for f in formula_links) if formula_links else "Входом 17 выданных формул ВАК не является. Применимость как признака модели ещё не проверялась.")
            if near:
                body += "\n\n## Статистически близкие сигналы\n\n" + near
            body += f"\n\nСинхронизировать по date; для окна признаков использовать только данные, доступные к моменту решения. {link(path, 'Связи и синхронизация.md')}. Метод расчёта: {link(path, PROOF)} (telemetry_profile.json; profile_data.py)."
            add(path, f"{'AVT' if stage == 'avt' else 'HT'}-{tag}: {meaning}", body, "signal", parent, id=f"{stage}:{tag}", unit_status="unknown", control_status="unknown")
            catalog.append((link(parent, path, tag), meaning, fmt(p["median"]), fmt(p["min"]), fmt(p["max"])))
        skeleton = table(["Колонки", "Как читать"], [("date", "Общий временной ключ; строка YYYY-MM-DD HH:MM:SS, часовой пояс не указан"), (", ".join(timing["service_columns"]), "Служебные индексы экспорта; не признаки и не время"), (f"{timing['signals']} колонок сигналов", "Числа с десятичной точкой; описания и единицы проверять в дочерних заметках")])
        add(parent, title, f"Файл `data/{filename}`: {timing['rows']} строк данных, {timing['signals']} сигналов. CSV с разделителем запятая и одной строкой заголовка.\n\n## Скелет таблицы\n\n{skeleton}\n## Покрытие\n\n{coverage(timing)}\nПолная регулярная сетка, пропущенных ячеек сигналов 0. Временные метки обоих CSV совпадают. Это позволяет соединить телеметрию по date после добавления префиксов установки. Одинаковые имена T6/F26 в двух файлах означают разные сигналы.\n\n## Чтение\n\n1. Прочитать CSV, разобрать date, сохранить имена колонок.\n2. Исключить служебные индексы из признаков, оставить ссылку на строку для аудита.\n3. Добавить stage к идентичности тега. Проверить сортировку, дубли и свежесть.\n4. Прочитать ограничения нужных сигналов; отсутствие NaN не отменяет плато и сомнений в единицах.\n\n## Все сигналы\n\n{table(['Тег', 'Описание из КИП', 'Медиана', 'Min', 'Max'], catalog)}\nСвязи: {link(parent, REF)}, {link(parent, VAK)}, {link(parent, SCHEME)}, {link(parent, ISSUES)}. Исторические диапазоны приведены без очистки, в неподтверждённых единицах экспорта.", "source", SOURCES, source_file=f"data/{filename}")

    # Independent laboratory pairs, including malformed values in examples.
    labhead = labbook["sheets"][0]["head"]
    def column_index(letters):
        n = 0
        for c in letters:
            n = n * 26 + ord(c) - 64
        return n - 1
    for pid, records in groups.items():
        parent = point_path(pid)
        for p in records:
            path = lab_path(p)
            a, b = p["excel_columns"].split(":")
            col = column_index(a)
            examples = [(r["excel_row"], r["values"][col], r["values"][col+1]) for r in labhead if r["excel_row"] >= 5 and len(r["values"]) > col+1 and r["values"][col] is not None][:3]
            parameter = p["parameter"]
            quality = ["Временная метка источника не подтверждена как время доступности анализа; см. Q03."]
            warnings = ["Q03-Время-и-доступность"]
            if pid == "AVT1" and parameter in ("50%.T", "EBP.T", "D15", "I350"):
                quality.append("Единица в исходной строке 3 расходится с ожидаемым смыслом показателя. Значения оставлены в исходном масштабе, исправление не подтверждено.")
                warnings.append("Q02-Единицы-ЛИМС")
            if p["nonnumeric_examples"] or p["declared_count"] != p["rows"] or parameter == "CloudPoint_1":
                quality.append(f"Заявлено {p['declared_count']}, датированных записей {p['rows']}, числовых {p['count']}. Нечисловые значения: {json.dumps(p['nonnumeric_examples'], ensure_ascii=False)}. Счётчик не использовать вместо фактического числа проб.")
                warnings.append("Q10-Служебные-ЛИМС")
            if p["zero_count"]:
                quality.append(f"В ряду {p['zero_count']} нулей. Проверка физической правдоподобности зависит от показателя; нули автоматически не удалялись.")
            if p["negative_count"]:
                quality.append(f"В ряду {p['negative_count']} отрицательных значений. Для холодных свойств знак сам по себе не является ошибкой.")
            if p["count"] < 150:
                quality.append("Меньше 150 числовых проб: высок риск нестабильной оценки модели и редкого покрытия режимов. Не увеличивать размер выборки переносом одной метки на 10-минутную сетку.")
            if parameter == "Mg.Sulfur":
                quality.append("230 из 1462 результатов выше 10 мг/кг; максимум 2120 требует отдельной проверки. 1458 числовых результатов входят в период телеметрии.")
                warnings.append("Q06-Экстремальная-сера")
            related = [concept_path(prop(parameter)), parent]
            if pid == "HT2" and parameter in ("Mg.Sulfur", "D15"):
                related.append(pak_path("sulfur" if parameter == "Mg.Sulfur" else "density"))
            targets = [f for f in formulas if prop(f["name"].split(":")[-1]) == prop(parameter)]
            body = f"**Исходная точка:** {p['point']}\n\n**Показатель:** `{parameter}`. {link(path, concept_path(prop(parameter)), 'Что означает показатель')}.\n\n" + table(["Поле", "Содержание"], [("Файл и лист", f"{labbook['file']}; {labbook['sheets'][0]['sheet']}"), ("Пара столбцов", f"{a}: дата, {b}: значение; измерения с строки 5"), ("Заголовки", f"{a}1/{b}1: точка (может быть пустой частью общего заголовка); {a}2: показатель; {a}3: единица; {a}4: заявленный счётчик"), ("Единица источника", p["unit_source"]), ("Объект строки", "Один результат одного показателя одной точки; не вся проба целиком"), ("Записей с датой / числовых", f"{p['rows']} / {p['count']}"), ("Числовых внутри периода CSV", p["within_telemetry_valid"])])
            if parameter == "Mass.Sulfur":
                body += "\nЯвная конвертация в мг/кг: `value_mg_kg = value_source * 10000`. Входную серу нельзя сравнивать с выходной до конвертации; пробам разных точек также нужен транспортный лаг.\n"
            body += f"\n## Примеры из Excel\n\n{table(['Строка', a + ' (дата)', b + ' (raw)'], examples)}\n## Покрытие и распределение\n\n{coverage(p)}\n{stats(p)}\nСтатистика по распознанным числам за весь период ряда без удаления выбросов; время учитывает все датированные записи, включая служебные. Максимальный разрыв не задаёт допустимый возраст анализа.\n\n## Правила чтения и ограничения\n\n" + "\n".join(f"- {x}" for x in quality)
            body += "\n\n" + "; ".join(link(path, issue_path(x)) for x in warnings)
            body += "\n\n## Связи\n\n" + "\n".join(f"- {link(path, x)}" for x in related)
            if targets:
                body += "\n\nРодственные по свойству ВАК (совпадение точки/фракции и методики не подтверждено):\n\n" + "\n".join(f"- {link(path, f['path'], f['name'])}" for f in targets)
            body += f"\n\nНе соединять этот ряд с соседней парой по номеру строки. {link(path, 'Связи и синхронизация.md')}. Основание: {link(path, PROOF)} (profile_summary.json -> lims, ключи point + parameter + excel_columns)."
            add(path, f"{pid}: {parameter}", body, "lab-series", parent, id=f"LIMS:{pid}:{parameter}:{a}-{b}", unit_source=p["unit_source"])
        note = "Для ГО-1 рабочая интерпретация - сырьё, для ГО-2 - гидроочищенный продукт. Точная линия, транспортный лаг и связь с товарным блендом не подтверждены." if pid.startswith("HT") else "Номер точки не задаёт автоматически фракцию 240-350/350 из ВАК и не является номером аппарата на схеме. Для АВТ-1 название продукта в ЛА и выгрузке различается."
        add(parent, POINT_NAMES[pid], f"**Название в выгрузке:** {records[0]['point']}\n\n{note}\n\nВ точке {len(records)} независимых рядов, {sum(p['count'] for p in records)} числовых результатов. Не все показатели измерены у одной и той же пробы.\n\n" + table(["Ряд", "Колонки", "Единица raw", "Числовых", "Период"], [(link(parent, lab_path(p), p["parameter"]), p["excel_columns"], p["unit_source"], p["count"], p["start"][:10] + " .. " + p["end"][:10]) for p in records]) + f"\nСвязи: {link(parent, 'Источники/Справочник/ЛА.md')}, {link(parent, concept_path('Точка отбора и фракция'))}, {link(parent, issue_path('Q03-Время-и-доступность'))}.", "sample-point", LIMS, id=pid)
    add(LIMS, "ЛИМС: лабораторные анализы", f"Файл `{labbook['file']}`, лист `{labbook['sheets'][0]['sheet']}`. 108 колонок: 54 независимые пары дата/значение в 6 точках. Всего 36806 записей с датой, из них 36800 числовых и 6 `Pt Created`. В строке счётчиков заявлено 36808.\n\n## Скелет Excel\n\n" + table(["Строка/колонки", "Назначение"], [("1", "Название точки, общие/разреженные заголовки; распространять только в зоне заголовка"), ("2", "Имя показателя для пары"), ("3", "Исходная единица; некоторые единицы спорные"), ("4", "Заявленное количество; проверять фактические записи"), ("5 и далее", "Измерения: дата слева, raw-значение справа"), ("A:B, C:D, ... DC:DD", "54 отдельных ряда; дата соседней пары может быть другой")]) + "\n## Чтение в длинный формат\n\n1. Обходить пары столбцов, восстановить точку только по строке заголовка.\n2. Для каждой пары сохранить parameter, unit_source, source_columns и source_row.\n3. Разобрать собственную дату и число; Pt Created сохранить как raw с флагом, числовое значение null.\n4. Объединить пары вертикально: одна строка на результат, идентификатор включает точку и пару.\n5. Не заполнять целевые метки вперёд ради увеличения числа проб; отдельно считать возраст последнего доступного анализа.\n\nРекомендуемые поля: `series_id, point_raw, parameter_raw, unit_source, event_time, available_at, value_raw, value, quality_flags, source_columns, source_row`. available_at пока неизвестен; не заполнять его временем пробы без маркировки допущения.\n\n## Точки и все ряды\n\n" + table(["Точка", "Рядов", "Числовых"], [(link(LIMS, point_path(pid)), len(ps), sum(p["count"] for p in ps)) for pid, ps in groups.items()]) + f"\nПодробные примеры и статистика каждой пары находятся в дочерних карточках. См. {link(LIMS, issue_path('Q02-Единицы-ЛИМС'))}, {link(LIMS, issue_path('Q10-Служебные-ЛИМС'))}, {link(LIMS, 'Связи и синхронизация.md')}.", "source", SOURCES, source_file=labbook["file"])

    for key, p in summary["pak"].items():
        path = pak_path(key)
        col = 0 if key == "sulfur" else 3
        pair = "A:B" if col == 0 else "D:E"
        examples = [(r["excel_row"], r["values"][col], r["values"][col+1]) for r in pakbook["sheets"][0]["head"] if r["excel_row"] in (3, 4, 5)]
        extra = ""
        if key == "sulfur":
            extra = f"Выше 10: {p['above_10']} строк (12.0459%). Это доля архивных точек при предположении массового ppm, не доля забракованных партий.\n\n" + table(["Начало плато", "Конец", "Значение", "Строк", "Суток"], [(r["start"], r["end"], fmt(r["value"]), r["rows"], fmt(r["elapsed_days"])) for r in findings["pak_sulfur_constant_runs"]])
            extra += f"\n{link(path, issue_path('Q04-Плато-ПАК'))}; {link(path, issue_path('Q09-ПАК-алиас'))}; {link(path, issue_path('Q06-Экстремальная-сера'))}."
        else:
            extra = "В справочнике ПАК!A3 прямо указана расчётная плотность при 15C. Начало только в марте 2025; последняя точка через 244 секунды после предыдущей, остальные интервалы 600 секунд. Не заполнять 2023-2024 будущими значениями и не считать ряд независимым приборным эталоном."
        lab = next(p for p in labs if point_id(p["point"]) == "HT2" and p["parameter"] == ("Mg.Sulfur" if key == "sulfur" else "D15"))
        add(path, p["tag"], f"Файл `{pakbook['file']}`, `Лист1`, пара `{pair}`: собственная дата слева, число справа, данные с строки 3. Единица заголовка: **{p['unit']}**. Имя в строке 1, единица в строке 2.\n\n{table(['Строка', 'Дата', 'Значение'], examples)}\n## Покрытие\n\n{coverage(p)}\n## Распределение\n\n{stats(p)}\n{extra}\n\n## Использование\n\nСоединять по времени с ограничением возраста и флагом неизменности. Приоритет ниже лаборатории, выше непроверенной формулы ВАК.\n\nРодственный лабораторный ряд: {link(path, lab_path(lab))}; это кандидат сопоставления, точная точка и задержка требуют подтверждения.\n\nПонятие: {link(path, concept_path('Сера' if key == 'sulfur' else 'Плотность D15'))}. Основание: {link(path, PROOF)} (profile_summary.json -> pak; findings_checks.json).", "analyzer", PAK, id=p["tag"], unit_source=p["unit"])
    add(PAK, "ПАК: поточные анализаторы", f"Файл `{pakbook['file']}`, один лист `Лист1`. В нём **две независимые таблицы**, а не одна общая строка состояния.\n\n" + table(["Пара", "Ряд", "Единица", "Число точек", "Начало"], [("A:B", link(PAK, pak_path("sulfur")), "ppm", 189649, "2023-01-01"), ("D:E", link(PAK, pak_path("density")), "кг/м3", 75455, "2025-03-05 10:20")]) + "\nКолонка C пустая. В строке 1 идентификаторы, в строке 2 единицы, с строки 3 данные. Например, в строке 3 сера относится к 2023-01-01, плотность к 2025-03-05. Слияние по строке создаст ложные пары.\n\nРекомендуемый длинный формат: `analyzer_id, event_time, value_raw, value, unit_source, available_at, unchanged_duration, quality_flags, source_row`.\n\nСначала разделить A:B и D:E, затем разобрать собственные даты, проверить плато и только потом соединять по времени. Часть ПАК продолжается после конца CSV; такие точки не имеют полного входного состояния телеметрии.\n\n" + f"См. {link(PAK, 'Источники/Справочник/ПАК-справочник.md')}, {link(PAK, 'Связи и синхронизация.md')}, {link(PAK, issue_path('Q04-Плато-ПАК'))}.", "source", SOURCES, source_file=pakbook["file"])

    for f in formulas:
        path = f["path"]
