    pages = [(1, "К1 и подготовка нефти", "На странице видны К1, узлы предварительного нагрева и ЭЛОУ. Схема помогает читать названия потоков и аппаратов; точные короткие CSV-теги не нанесены в надёжно сопоставимом виде."), (2, "К2 и атмосферная ректификация", "Показана атмосферная колонна К2, боковые отборы и отпарные узлы, в том числе К9 и дизельные фракции. Номер лабораторной точки из Excel нельзя автоматически приравнять линии на этой схеме."), (3, "К10 и вакуумная часть", "Показана вакуумная часть с К10, потоками тяжёлых фракций и остатка. Это контекст АВТ; схемы ГО и блендинга в выданном PDF нет.")]
